h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Northern Range · calques jour et nuit</title><style>*{box-sizing:border-box}body{background:#111b2b;color:#e9eff9;font:16px system-ui;margin:0}header,main,footer{max-width:1160px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#b9c9df;line-height:1.6}.eyebrow{color:#b5caff;font-size:12px;letter-spacing:2px}.bar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px}select,button{background:#283c57;color:#f2f6ff;border:1px solid #607997;border-radius:7px;padding:11px;cursor:pointer}.view{display:grid;grid-template-columns:minmax(0,1fr) 245px;gap:24px}canvas{width:100%;image-rendering:pixelated;background:repeating-conic-gradient(#28354a 0% 25%,#243045 0% 50%) 50%/20px 20px}aside{padding:16px;background:#1a2a41;border-radius:8px}label{display:block;margin:14px 0;font-size:14px}a{color:#b2ddff}footer{border-top:1px solid #3b506c;font-size:14px}@media(max-width:800px){.view{grid-template-columns:1fr}}</style><header><div class="eyebrow">NOUVELLE RÉFÉRENCE / CALQUES ÉDITABLES</div><h1>Northern Range — arène centrale</h1><p>Jour et nuit, lune et étoiles indépendantes, brume légère en overlay. Les rochers sont redisposés autour d’une arène dégagée au centre.</p></header><main><div class="bar"><select id="project"><option value="northern">Northern Range</option><option value="caves">Crooked Cavern · statique</option><option value="spring">Spring · pulsation corrigée</option></select><select id="variant"><option value="nuit">Nuit</option><option value="jour">Jour</option></select><button id="pause">Pause Spring</button><button id="export">Exporter la composition</button></div><div class="view"><section><canvas id="view" width="456" height="432"></canvas><p id="status"></p></section><aside><b>Calques indépendants</b><div id="layers"></div><p><small>La flèche ↓ télécharge le calque sélectionné. Seul le Spring est animé dans cet aperçu.</small></p></aside></div><p id="note"></p></main><footer>Références conservées : fichier Northern Range ajouté par l’utilisateur au commit 00cb874 ; carte Halcyon et ressources PMDO documentées dans les packs précédents. Terrains Northern guidés par la référence, non certifiés natifs. Pas de validation PMDO/GPU.</footer><script>const DATA=__DATA__;function image(src){const im=new Image();im.src=src;return im}function decode(o){if(typeof o==='string')return image(o);if(Array.isArray(o))return o.map(decode);return Object.fromEntries(Object.entries(o).map(([k,v])=>[k,decode(v)]))}const I=decode(DATA),c=document.getElementById('view'),ctx=c.getContext('2d');let project='northern',variant='nuit',visible={},time=0,last=null,running=true;function save(src,name){const a=document.createElement('a');a.href=src;a.download=name;a.click()}function items(){if(project==='spring')return{decor:'Décor et escalier',cycle3:'Eau native · cycle 3',cycle13:'Lumière native · cycle 13',foundation:'Colonne nettoyée',pulse:'Couleurs fixes · pulsation'};return Object.fromEntries(Object.keys(DATA[project][variant]).map(n=>[n,n.replace('.png','').replaceAll('_',' ')]))}function current(k){if(project!=='spring')return DATA[project][variant][k];const f=Math.floor(time*12/1000)%78,nf=Math.floor(f/2);if(k==='pulse')return DATA.spring.pulse[f];if(k==='cycle3')return DATA.spring.cycle3[nf%3];if(k==='cycle13')return DATA.spring.cycle13[nf%13];return DATA.spring[k]}function setup(){visible={};const root=document.getElementById('layers');root.innerHTML='';for(const [k,n]of Object.entries(items())){visible[k]=true;const label=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>visible[k]=ch.checked;a.href='#';a.textContent=' ↓';a.onclick=e=>{e.preventDefault();save(current(k),k+'.png')};label.append(ch,document.createTextNode(' '+n),a);root.append(label)}c.width=project==='northern'?456:project==='caves'?320:600;c.height=project==='northern'?432:project==='caves'?240:600;document.getElementById('note').textContent=project==='northern'?'L’arène couvre le centre exact du canvas. Calques de profondeur séparés ; les surfaces cachées derrière les rochers ne sont pas reconstruites.':project==='caves'?'Trois compositions fixes, sans particules ni animation. Dessin rocheux canonique recoloré en gris, entrée et blocs repositionnés.':'Couleurs de la colonne fixes : seule leur opacité pulse en 6,5 s. Une base propre remplace les pixels texturés parasites dans la colonne ; bassin turquoise et escalier conservés.'}document.getElementById('project').onchange=e=>{project=e.target.value;const v=document.getElementById('variant');v.innerHTML='';const opts=project==='northern'?[['nuit','Nuit'],['jour','Jour']]:project==='caves'?[['01','Entrée centrale'],['02','Entrée à gauche'],['03','Entrée à droite']]:[['pulse','Pulsation']];for(const [value,text]of opts){const o=document.createElement('option');o.value=value;o.textContent=text;v.append(o)}variant=opts[0][0];setup()};document.getElementById('variant').onchange=e=>{variant=e.target.value;setup()};document.getElementById('pause').onclick=e=>{running=!running;e.target.textContent=running?'Pause Spring':'Reprendre Spring'};document.getElementById('export').onclick=()=>save(c.toDataURL(),project+'_'+variant+'.png');function draw(im){if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}function frame(t){if(last!==null&&running)time+=t-last;last=t;ctx.clearRect(0,0,c.width,c.height);if(project==='spring'){const f=Math.floor(time*12/1000)%78,nf=Math.floor(f/2);for(const k of ['decor','cycle3','cycle13','foundation','pulse'])if(visible[k])draw(k==='cycle3'?I.spring.cycle3[nf%3]:k==='cycle13'?I.spring.cycle13[nf%13]:k==='pulse'?I.spring.pulse[f]:I.spring[k]);document.getElementById('status').textContent='Pulsation · phase '+(f+1)+'/78 · 6,5 s'}else{for(const [k,im]of Object.entries(I[project][variant]))if(visible[k])draw(im);document.getElementById('status').textContent='Composition statique · '+c.width+' × '+c.height}requestAnimationFrame(frame)}setup();requestAnimationFrame(frame);</script></html>'''
